package com.hbm.missile.completion.volcano;
import com.hbm.hazard.HbmHazards;import java.util.*;import net.minecraft.core.registries.Registries;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.registries.*;
public final class VolcanoContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");public static final DeferredBlock<VolcanoBlock> NORMAL=BLOCKS.register("volcano_core",()->new VolcanoBlock(false)),RADIOACTIVE=BLOCKS.register("volcano_rad_core",()->new VolcanoBlock(true));public static final DeferredItem<VolcanoItem> NORMAL_ITEM=ITEMS.register("volcano_core",()->new VolcanoItem(NORMAL.get())),RADIOACTIVE_ITEM=ITEMS.register("volcano_rad_core",()->new VolcanoItem(RADIOACTIVE.get()));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<VolcanoBlockEntity>> ENTITY=ENTITIES.register("volcano_core",()->BlockEntityType.Builder.of(VolcanoBlockEntity::new,NORMAL.get(),RADIOACTIVE.get()).build(null));public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);bus.addListener(VolcanoSmokeEffects::register);}public static List<ItemStack> creativeStacks(String tab){if(!tab.equals("nuke"))return List.of();var out=new ArrayList<ItemStack>();for(var item:List.of(NORMAL_ITEM,RADIOACTIVE_ITEM))for(int i=0;i<5;i++){var stack=new ItemStack(item.get());stack.set(HbmHazards.LEGACY_METADATA.get(),i);out.add(stack);}return out;}private VolcanoContent(){}
}
